(function(global){
  'use strict';
  // Portable, self-contained version — used only when a generated/exported
  // report needs to be a single standalone file (DOCX/PDF/email attachment)
  // with no external image dependency. Kept small (~520KB vs the old
  // 1.6MB) via PNG palette quantization; the banner has no transparency,
  // so RGB + 256-color quantization is visually lossless at print size.
  var DATA_URI = 'data:image/png;base64,';

  // On-screen version — loaded once as a real file and cached by the
  // browser across all pages, instead of being re-parsed as a giant JS
  // string literal on every single page load.
  var BANNER_ASSET_URL = 'assets/arc-report-banner.webp';

  var CSS = '.arc-report-banner{margin:0 0 24pt;text-align:center}.arc-report-banner img{width:100%;max-width:7.25in;height:auto;display:block;margin:0 auto}.arc-report-banner.compact img{max-width:6.5in}';

  function html(className, opts) {
    var portable = opts && opts.portable;
    var src = portable ? DATA_URI : BANNER_ASSET_URL;
    return '<div class="' + (className || 'arc-report-banner') + '"><img src="' + src + '" alt="ARC Investigations and Consulting confidential report header"></div>';
  }

  global.ARC_REPORT_HEADER = { dataUri: DATA_URI, bannerAssetUrl: BANNER_ASSET_URL, css: CSS, html: html };
  global.ARC_BANNER_DATAURI = DATA_URI;
  global.ARC_BANNER = DATA_URI;
})(typeof window !== 'undefined' ? window : globalThis);
